def encode(message):
    vowels = 'aeiouAEIOU'
    encoded_message = []

    for char in message:
        if char in vowels:
            # Replace vowel with the letter two places ahead
            if char.islower():
                new_char = chr(ord(char) + 2)
            else:
                new_char = chr(ord(char) + 2).upper()
            encoded_message.append(new_char)
        else:
            # Swap case for non-vowel characters
            encoded_message.append(char.swapcase())

    return ''.join(encoded_message)

